import sys
import types
from typing import Any, Dict, Iterator, Tuple

INSTALLED = False


class _RegistryView:
    """Read-only mapping view over the generated vendored registry."""

    def __init__(self, inner: Any) -> None:
        self._inner = inner

    def __contains__(self, name: str) -> bool:
        return name in self._inner

    def __getitem__(self, name: str) -> Any:
        return self._inner[name]

    def get(self, name: str, default: Any = None) -> Any:
        return self._inner.get(name, default)

    def keys(self):
        return self._inner.keys()

    def items(self) -> Iterator[Tuple[str, Any]]:
        for name in list(self._inner.keys()):
            yield name, self._inner[name]

    def values(self) -> Iterator[Any]:
        for _, value in self.items():
            yield value

    def __iter__(self) -> Iterator[str]:
        return iter(list(self._inner.keys()))

    def __len__(self) -> int:
        return len(list(self._inner.keys()))


