    """Expose this platform's document index as ``vendor.cerebrum.core.vector_store``."""
    name = "vendor.cerebrum.core.vector_store"
    if name in sys.modules:
        return
    try:
        import vendor.cerebrum.core as core  # noqa: F401
    except Exception:  # noqa: BLE001 - vendor absent is the honest no-op
        return
    from app import retrieval

    module = types.ModuleType(name)
    module.__doc__ = (
        "Adapter installed by app.vendor_compat: this platform's tenant-scoped "
        "document index, exposed under the name the vendored knowledge block "
        "imports."
    )
    module.search_vectors = retrieval.search_vectors
    module.upsert_vectors = retrieval.upsert_vectors
    module.delete_vectors = retrieval.delete_vectors
    module.__all__ = ["search_vectors", "upsert_vectors", "delete_vectors"]
    sys.modules[name] = module
    try:
