    except Exception:  # noqa: BLE001
        pass


def install_registry_items() -> None:
    """Add a mapping ``items()`` view to the generated vendored registry."""
    try:
        from vendor.cerebrum import blocks as blocks_pkg
    except Exception:  # noqa: BLE001
