def render() -> Tuple[str, List[Dict[str, Any]]]:
    """The exact bytes of app/static/index.html, from the sources in frontend/."""
    for needed in (SHELL, CONSOLE):
        if not needed.is_file():
            raise SystemExit("build cannot run: %s is missing" % needed.relative_to(ROOT))
    shell = SHELL.read_text(encoding="utf-8")
    console = CONSOLE.read_text(encoding="utf-8")
    roster = declared_roster()
    page = shell.replace(CONSOLE_PLACEHOLDER, console).replace(
        ROSTER_PLACEHOLDER, _ids_script(roster)
    )
    for placeholder in (CONSOLE_PLACEHOLDER, ROSTER_PLACEHOLDER):
        if placeholder in page:
            raise SystemExit("build cannot run: %s was not substituted" % placeholder)
    return page, roster


def main() -> int:
    page, roster = render()
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(page, encoding="utf-8")
    sys.stdout.write(
        "wrote %s (%d bytes, %d capability id(s) inlined, %d declared field(s) "
        "checked from app/models.py)\n"
        % (
            OUT.relative_to(ROOT),
            len(page),
            len(roster) or len(EXPECTED_CAPABILITIES),
            sum(len(cap["fields"]) for cap in roster),
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
